#include <WiFi.h>
#include <Wire.h>
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <DHT.h>
#include <LiquidCrystal_I2C.h>

DHT dht(14, DHT11);
LiquidCrystal_I2C lcd(0x27, 16, 2);
Adafruit_ST7789 tft = Adafruit_ST7789(-1, 9, 10);

void setup() {
  Serial.begin(115200);
  dht.begin();
  pinMode(13, INPUT); // Chân PIR (GPIO 13) hoạt động độc lập
  Wire.begin(8, 18);
  lcd.init(); lcd.backlight();

  // Đặt MISO = -1 để giải phóng GPIO 13 cho cảm biến PIR
  SPI.begin(12, -1, 11, -1); 
  tft.init(240, 240, SPI_MODE2);
  tft.fillScreen(0x0000);

  ledcAttach(41, 50, 16);
  ledcAttach(42, 50, 16);
  WiFi.softAP("ESP32-S3-Robot", "12345678");
}

void loop() {
  float t = dht.readTemperature();
  int motion = digitalRead(13);
  lcd.setCursor(0, 1);
  lcd.print(motion ? "Motion!" : "Safe   ");
  tft.fillScreen(motion ? 0xF800 : 0x07E0);
  delay(1000);
}
